// ELEMENTS:
// 1. Fundo navy; foto (src) por trás de 6 persianas navy que abrem uma a uma, com um fio azul IAD
// 2. Zoom-out lento
// 3. Barra azul IAD + eyebrow + legenda em serifa branca no rodapé
// 4. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { MediaImg as Img } from "../media";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#001F44";
const NAVY_RGB = "0,31,68";
const CYAN = "#DE212B";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.24) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};


const PersianaRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const u = format === "landscape" ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const eyebrow = String(p.eyebrow ?? "").trim();
  const caption = String(anim.text ?? "").trim();

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 22 * u}px)` };
  };
  const zoom = interpolate(f, [0, T], [1.12, 1.02], { ...clamp, easing: Easing.out(Easing.sin) });
  const N = format === "landscape" ? 8 : 6;
  const bar = show(0.9, 0.7) * 128 * u;

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: NAVY }}>
      <AbsoluteFill style={{ transform: `scale(${zoom})` }}>
        {src ? <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)" }} /> : null}
      </AbsoluteFill>
      {/* Navy blinds that open one after the other, left to right, each with a cyan edge. */}
      <AbsoluteFill style={{ display: "flex", flexDirection: "row" }}>
        {Array.from({ length: N }, (_, i) => {
          const open = show(0.1 + i * 0.09, 0.85);
          return (
            <div key={i} style={{ flex: 1, height: "100%", position: "relative" }}>
              <div style={{ position: "absolute", top: 0, bottom: 0, right: 0, width: `${(1 - open) * 100}%`, background: NAVY }} />
              <div style={{ position: "absolute", top: 0, bottom: 0, right: `${(1 - open) * 100}%`, width: 2 * u, background: CYAN, opacity: open > 0 && open < 1 ? 0.9 : 0 }} />
            </div>
          );
        })}
      </AbsoluteFill>
      {caption ? (
        <>
          <AbsoluteFill style={{ background: `linear-gradient(180deg, rgba(${NAVY_RGB},0) 55%, rgba(${NAVY_RGB},0.86) 100%)`, opacity: show(0.8) }} />
          <div style={{ position: "absolute", left: 72 * u, right: 72 * u, bottom: (format === "portrait" ? 184 : 72) * u, display: "flex", flexDirection: "column", gap: 24 * u }}>
            <div style={{ display: "flex", alignItems: "center", gap: 28 * u }}>
              <div style={{ width: bar, height: 4 * u, background: CYAN }} />
              {eyebrow ? (
                <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 38 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(1.0) }}>{eyebrow}</div>
              ) : null}
            </div>
            <div style={{ fontFamily: FONTS.display, fontVariantNumeric: "lining-nums", fontWeight: 300, fontSize: 96 * u, lineHeight: 1.05, color: WHITE, ...rise(1.1) }}>{caption}</div>
          </div>
        </>
      ) : null}
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: 6 * u, background: "#DE212B" }} />
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default PersianaRevelacao;
